#############################################################################
# Default syslog-ng.conf file which collects all local logs into a
# single file called /var/log/messages tailored to container usage.

@version: 3.38

options {
    # enable verbose logging (needs 4.0)
    # log-level(verbose);

    # enable debug messages
    # stats_freq(1);  # Update statistics every 1 second
    flush_lines(0);
};

source s_network {
    udp(port(514));
};

destination d_local {
    file("/var/log/syslog");
};

destination d_stdout {
    # send logs to stdout
    file("/dev/stdout");
};

log {
    source(s_network);
    destination(d_stdout);
    destination(d_local);
};

{
  "docker": {
    "mounts": [
      "type=bind,source=cfg/boot.sh,target=/boot.sh",
      "type=bind,source=cfg/tac_plus.conf,target=/etc/tac_plus.conf"
    ]
  },
  "shell": "/bin/bash",
  "day0cmd": [ "/bin/bash", "/boot.sh" ],
  "busybox": true
}

key = tacacs123
accounting file = /var/log/tacplus-acct.log
acl = default {
  permit = 0.0.0.0
}
host = 0.0.0.0 {
  prompt = "TACACS+ auth: "
}
group = netadmin {
  default service = permit
  service = exec {
    priv-lvl = 15
  }
}
group = netoper {
  default service = permit
  service = exec {
    priv-lvl = 1
  }
}
user = $enab15$ {
  login = cleartext admin123
}
user = tacadmin {
  login = cleartext admin123
  member = netadmin
}
user = tacoper {
  login = cleartext oper123
  member = netoper
}

{
  "busybox": false,
  "docker": {
    "mounts": [
      "type=bind,source=cfg,target=/config",
      "type=bind,source=cfg/../tmp,target=/tmp"
    ],
    "misc_args": ["--device", "/dev/null:/dev/null:rw"]
  }
}
